<script setup>
import { ref,watch } from 'vue'; import { useRoute } from 'vue-router'; import { api } from '../api';
const route=useRoute(),rows=ref([]),loading=ref(false); async function load(){loading.value=true;rows.value=(await api.get('/'+route.meta.resource)).data;loading.value=false}watch(()=>route.meta.resource,load,{immediate:true});
function val(v){if(Array.isArray(v))return v.map(x=>typeof x==='object'?JSON.stringify(x):x).join(', ');if(v&&typeof v==='object')return JSON.stringify(v);if(typeof v==='string'&&v.includes('T')&&!isNaN(Date.parse(v)))return new Date(v).toLocaleDateString('en-SG');return v}
</script>
<template><div class="section-head"><div><h3>{{route.meta.title}}</h3><span>Role-filtered operational data</span></div><button class="btn secondary" @click="load">Refresh</button></div><div class="card table-wrap"><table v-if="rows.length" class="table"><thead><tr><th v-for="k in Object.keys(rows[0]).filter(k=>!['password','items'].includes(k))" :key="k">{{k.replaceAll(/([A-Z])/g,' $1')}}</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td v-for="k in Object.keys(rows[0]).filter(k=>!['password','items'].includes(k))" :key="k"><span v-if="k==='status'" class="pill">{{r[k]}}</span><template v-else>{{val(r[k])}}</template></td></tr></tbody></table><div v-else class="empty">{{loading?'Loading…':'No records available.'}}</div></div></template>
